CREATE TRIGGER learnings_project_id_insert AFTER INSERT ON learnings
      WHEN NEW.project_id IS NULL AND NEW.project_slug IS NOT NULL
      BEGIN
        UPDATE learnings SET project_id = (SELECT project_id FROM project_keys WHERE slug = NEW.project_slug AND collided = 0) WHERE rowid = NEW.rowid;
      END;
CREATE TRIGGER learnings_project_id_update AFTER UPDATE OF project_slug ON learnings
      WHEN NEW.project_slug IS NOT OLD.project_slug
      BEGIN
        UPDATE learnings SET project_id = CASE WHEN NEW.project_slug IS NULL THEN NULL
          ELSE (SELECT project_id FROM project_keys WHERE slug = NEW.project_slug AND collided = 0) END WHERE rowid = NEW.rowid;
      END;
